from inspect import signature

def generic(*e):
 def w(f):

 return f

 return w

def test_signature(f):
 print(signature(f))
 return f

@test_signature
@generic(T := int)
@test_signature
def foo(value: T):
 print(value)

foo(5)
foo("a")

output (Python 3.10.8):

(value: int)
(value: int)
5
